<script>
(function(){
  const size = 4;
  const boardEl = document.getElementById('grid');
  const scoreEl = document.getElementById('score');
  const bestEl = document.getElementById('best');
  const gainEl = document.getElementById('gain');
  const noticeEl = document.getElementById('gameOver');
  const newBtn = document.getElementById('newGameBtn');
  const restartBtn = document.querySelector('.btn-restart');
  const modeBtns = document.querySelectorAll('.mode-btn');
  const boardWrap = document.querySelector('.board');
  const toast = document.getElementById('toast');

  let grid = [];
  let score = 0;
  let best = Number(localStorage.getItem('best2048') || 0);
  let mode = 'classic'; // or cupcakes

  bestEl.textContent = best;

  // Build 16 background cells once
  function buildBackground(){
    boardEl.innerHTML = '';
    for(let i=0;i<size*size;i++){
      const empty = document.createElement('div');
      empty.className = 'cell';
      boardEl.appendChild(empty);
    }
  }

  function reset(){
    score = 0;
    grid = Array.from({length:size}, _ => Array(size).fill(0));
    addRandomTile();
    addRandomTile();
    render();
    hideGameOver();
  }

  function addRandomTile(){
    const empties = [];
    for(let r=0;r<size;r++){
      for(let c=0;c<size;c++){
        if(grid[r][c] === 0) empties.push({r,c});
      }
    }
    if(!empties.length) return;
    const pick = empties[Math.floor(Math.random()*empties.length)];
    grid[pick.r][pick.c] = Math.random()<0.9 ? 2 : 4;
  }

  function render(){
    // remove any existing tiles (we'll fully re-render)
    // Keep background cells as first 16 children
    // So remove children after 16
    while(boardEl.children.length > size*size){
      boardEl.removeChild(boardEl.lastChild);
    }
    // Create tiles
    for(let r=0;r<size;r++){
      for(let c=0;c<size;c++){
        const v = grid[r][c];
        const tile = document.createElement('div');
        tile.className = 'tile -'+v;
        tile.textContent = displayValue(v);
        boardEl.appendChild(tile);
      }
    }
    scoreEl.textContent = score;
    if(score > best){
      best = score;
      localStorage.setItem('best2048', best);
      bestEl.textContent = best;
    }
    boardWrap.classList.toggle('skin-cupcakes', mode === 'cupcakes');
  }

  function displayValue(v){
    if(v === 0) return '';
    if(mode === 'classic') return String(v);
    // cupcakes mode: small "ingredient to dessert" emoji mapping
    const map = {
      2:'🥚',4:'🧈',8:'🍶',16:'🥣',32:'🧁',64:'🍰',
      128:'🎂',256:'🍮',512:'🍨',1024:'🍧',2048:'🍩'
    };
    return map[v] || '🍭';
  }

  function move(dir){
    // dir: 'left','right','up','down'
    let moved = false;
    let gained = 0;

    const range = [...Array(size).keys()];
    const rev = [...range].reverse();

    function slideLine(line){
      // remove zeros
      let arr = line.filter(x => x!==0);
      // merge
      for(let i=0;i<arr.length-1;i++){
        if(arr[i]!==0 && arr[i]===arr[i+1]){
          arr[i] *= 2;
          gained += arr[i];
          arr[i+1] = 0;
        }
      }
      arr = arr.filter(x => x!==0);
      while(arr.length < size) arr.push(0);
      return arr;
    }

    if(dir==='left'){
      for(let r of range){
        const before = grid[r].slice();
        const after = slideLine(before);
        if(!arraysEqual(before, after)) moved = true;
        grid[r] = after;
      }
    }
    if(dir==='right'){
      for(let r of range){
        const before = grid[r].slice().reverse();
        const after = slideLine(before).reverse();
        if(!arraysEqual(grid[r], after)) moved = true;
        grid[r] = after;
      }
    }
    if(dir==='up'){
      for(let c of range){
        const col = range.map(r => grid[r][c]);
        const after = slideLine(col);
        for(let r of range){
          if(grid[r][c] !== after[r]) moved = true;
          grid[r][c] = after[r];
        }
      }
    }
    if(dir==='down'){
      for(let c of range){
        const col = rev.map(r => grid[r][c]);
        const after = slideLine(col).reverse();
        for(let i=0;i<size;i++){
          const r = i;
          if(grid[r][c] !== after[i]) moved = true;
          grid[r][c] = after[i];
        }
      }
    }

    if(moved){
      score += gained;
      if(gained>0) showGain('+'+gained);
      addRandomTile();
      render();
      if(isGameOver()) showGameOver();
    }
  }

  function arraysEqual(a,b){
    if(a.length!==b.length) return false;
    for(let i=0;i<a.length;i++) if(a[i]!==b[i]) return false;
    return true;
  }

  function isGameOver(){
    // any empty?
    for(let r=0;r<size;r++) for(let c=0;c<size;c++) if(grid[r][c]===0) return false;
    // any mergeable neighbours?
    for(let r=0;r<size;r++){
      for(let c=0;c<size;c++){
        const v = grid[r][c];
        if(r+1<size && grid[r+1][c]===v) return false;
        if(c+1<size && grid[r][c+1]===v) return false;
      }
    }
    return true;
  }

  function showGameOver(){
    noticeEl.classList.add('show');
  }
  function hideGameOver(){
    noticeEl.classList.remove('show');
  }

  function showGain(text){
    gainEl.textContent = text;
    // position gain near Score box (rough)
    const sb = document.querySelector('.metas .box').getBoundingClientRect();
    const wrap = document.querySelector('.board-wrap').getBoundingClientRect();
    gainEl.style.left = (sb.left - wrap.left + 16) + 'px';
    gainEl.style.top = (sb.top - wrap.top - 6) + 'px';
    gainEl.classList.remove('show');
    // force reflow
    void gainEl.offsetWidth;
    gainEl.classList.add('show');
    setTimeout(()=>gainEl.classList.remove('show'), 500);
  }

  // Controls
  window.addEventListener('keydown', (e)=>{
    const key = e.key.toLowerCase();
    if(['arrowleft','a'].includes(key)) { e.preventDefault(); move('left'); }
    if(['arrowright','d'].includes(key)) { e.preventDefault(); move('right'); }
    if(['arrowup','w'].includes(key)) { e.preventDefault(); move('up'); }
    if(['arrowdown','s'].includes(key)) { e.preventDefault(); move('down'); }
    if(key==='n'){ reset(); }
  });

  // Swipe controls (simple)
  let tX=0, tY=0, isTouch=false;
  boardEl.addEventListener('touchstart', (e)=>{ 
    if(!e.touches.length) return;
    isTouch=true; tX=e.touches[0].clientX; tY=e.touches[0].clientY;
  }, {passive:true});
  boardEl.addEventListener('touchend', (e)=>{
    if(!isTouch) return;
    const dX = (e.changedTouches[0].clientX - tX);
    const dY = (e.changedTouches[0].clientY - tY);
    const absX = Math.abs(dX), absY = Math.abs(dY);
    const thresh = 24;
    if(Math.max(absX,absY) < thresh) return;
    if(absX > absY){ move(dX>0?'right':'left'); }
    else{ move(dY>0?'down':'up'); }
    isTouch=false;
  });

  // Buttons
  newBtn.addEventListener('click', ()=> reset());
  restartBtn.addEventListener('click', ()=> reset());

  modeBtns.forEach(btn=>{
    btn.addEventListener('click', ()=>{
      modeBtns.forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      mode = btn.dataset.mode;
      render();
    });
  });

  // Other games demo navigation
  document.querySelectorAll('.card.btn').forEach(card=>{
    card.addEventListener('click', ()=>{
      toast.textContent = 'Opening '+card.querySelector('.c-title').textContent+'…';
      toast.classList.add('show');
      setTimeout(()=>toast.classList.remove('show'), 1200);
    });
  });

  // Init
  buildBackground();
  reset();

})();
</script>
</body>
